#include "../core/material_program.h"
#include <iostream>
using namespace P4MapKit::Material;
int checks=0;void Check(bool value,const char* text){++checks;if(!value)throw std::runtime_error(text);}template<class F>void Refuses(F f,const char* category){++checks;try{f();}catch(const Refused& e){if(e.name==category)return;throw;}throw std::runtime_error("expected named program refusal");}
int main(){try{const auto program=NormalizeMaterialTraceDeclarations({"STORAGE sbo_buf0[] = { program.storage[0] }","LDC.F32 R0.x, buf0[2452]","MOV.F R0.z, R0.x","STORAGE sbo_buf1[] = { program.storage[9] }","LOAD.U R1.x, sbo_buf1[R0.x]"});Check(program.Lines.size()==3&&program.Storage.size()==2,"storage declaration does not execute");Check(program.OriginalLines==std::vector<std::size_t>{1,2,4},"original evidence indices preserved");Check(program.Storage[1].Name=="sbo_buf1"&&program.Storage[1].Binding==9&&program.Storage[1].OriginalLine==3,"declared name and binding retained");Check(program.Lines.back()=="LOAD.U R1.x, sbo_buf1[R0.x]","storage operation stays executable and unsupported independently");for(const auto& line:{"STORAGE buf0[] = { program.storage[0] }","STORAGE sbo_buf0[] = { program.storage[0] };","STORAGE sbo_buf0[] = { program.storage[-1] }","STORAGE sbo_buf0[] = { program.storage[4294967296] }","STORAGE sbo_buf0[] = { program.storage[0] } MOV.F R0, R1"})Refuses([&]{NormalizeMaterialTraceDeclarations({line,"MOV.F R0, R1"});},"material storage declaration");Refuses([&]{NormalizeMaterialTraceDeclarations({});},"material program budget");Refuses([&]{NormalizeMaterialTraceDeclarations({"STORAGE sbo_buf0[] = { program.storage[0] }"});},"material program empty");std::cout<<"native trace declaration checks="<<checks<<"\n";}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
